// C: Manual allocation and deallocation
int* data = (int*)malloc(sizeof(int) * 10);
if (data == NULL) { /* Handle error */ }

// Use memory
data[0] = 42;

// Release memory block to the OS
free(data);

// C++: RAII via Destructor
class ResourceGuard {
    int* ptr;
public:
    ResourceGuard(int s) : ptr(new int[s]) {}
    // Automatically cleans up upon scope exit
    ~ResourceGuard() { delete[] ptr; }
};

// C++: Smart Pointer (Automatic Management)
std::unique_ptr<char> buffer = std::make_unique<char>(1024);
// No explicit delete required.

// Java/C#: Object allocation on the managed heap
class Data {}
Data d = new Data();

// Object 'd' is now rooted (reachable).
d = null; 
// Object is now eligible for Garbage Collection.

// Java: GC hint (non-guaranteed)
System.gc();
